// The Railway project, as code. `railway config plan` previews, `railway config apply` applies.
// The two secrets are set once with `railway variables --set ...` and preserved here;
// the public domain is generated by Railway (`railway domain`) and not tracked.
import { defineRailway, github, postgres, preserve, project, service } from 'railway/iac'

const REGION = 'europe-west4' // Amsterdam

export default defineRailway(() => {
  const db = postgres('postgres', { region: REGION })

  const app = service('brian-tasks', {
    source: github('Alp-Balaj/brian-tasks', { branch: 'master' }),
    build: { builder: 'DOCKERFILE', dockerfilePath: 'Dockerfile' },
    replicas: { [REGION]: 1 },
    healthcheck: '/api/health',
    healthcheckTimeout: 60,
    env: {
      NODE_ENV: 'production',
      PORT: '3000', // the generated domain (`railway domain --port 3000`) targets this
      DATABASE_URL: db.env.DATABASE_URL,
      APP_PASSWORD: preserve(),
      SESSION_SECRET: preserve(),
    },
  })

  return project('brian-tasks', { resources: [app, db] })
})
